INSERT INTO movement_types (id, name, description) VALUES
('4d2cda4f-dd23-4e7e-b87b-f5969d04fc26', 'Sale', 'Movimiento en el que un producto es vendido a un cliente.'),
('b52f0836-ac7a-40b6-82f4-4ab733709db6', 'Restock', 'Cuando un producto es reabastecido en el inventario, ya sea porque se realizó un pedido a un proveedor o por cualquier otra razón.'),
('99dd9beb-3716-44d2-81d7-af00fbd96493', 'Customer Return', 'Cuando un cliente devuelve un producto que había comprado previamente.'),
('82224a82-c4e3-4d6e-bae2-5445aef60c99', 'Supplier Return', 'Si el negocio devuelve productos al proveedor por alguna razón (defectuoso, exceso, etc.).'),
('29d96148-e453-4bf9-aadf-b4beefeb49fb', 'Inventory Adjustment', 'Cuando se realiza un ajuste manual en el inventario, ya sea por errores de conteo o cambios no registrados.'),
('79c6569b-954e-4967-b73a-dbeb4d776213', 'Warehouse Transfer', 'Si el inventario se mueve de un almacén a otro, disminuyendo el inventario, disminuyendo el inventario en un almacén o aumentándolo en otro.'),
('80135205-3ac8-4663-8846-652faf937c7c', 'Destruction', 'Cuando un producto es destruido, ya sea por estar defectuoso o por caducidad.'),
('4e62bb29-c9db-433a-8d90-9bf41e726039', 'Damaged Goods', 'Cuando se detecta que un producto ha sido dañado y ya no es apto para la venta.');
